test('mergeCustomers removes fromId and moves invoices to intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Northwind Studio', email: 'n@northwind.example', tier: 'gold' },
    { id: 'C-002', name: 'Acme Corp', email: 'a@acme.example', tier: 'standard' },
  ];
  const invoices = [
    { number: 'INV-1', customerId: 'C-001' },
    { number: 'INV-2', customerId: 'C-002' },
    { number: 'INV-3', customerId: 'C-001' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.customers[0].id, 'C-002');
  assert.equal(r.value.invoices.length, 3);
